// Кейс: .qa/tests/monitoring/MON-015.md · план: .qa/e2e-app/specs/app.md (1.15)
// Долгий мониторинг BANCI_MONITOR_MINUTES минут (по умолчанию 5): приложение не падает (на переднем плане),
// таймер растёт без скачков назад, статус «תקין», листа «הניטור הופסק» нет → «כבה את המצלמה» → итог.
// ЗАПУСКАЕТ МОНИТОРИНГ (сеанс в «היסטוריה») — только с BANCI_MONITORING=1. Входящие звонки — вручную (MON-015).
import { by, assert } from '../../lib/appium.mjs';
import { requireMonitoringOptIn, startMonitoring, endMonitoring, timerSeconds } from '../../lib/monitoring.mjs';

export const name = 'Мониторинг N минут без падений: приложение на переднем плане, таймер растёт, статус «תקין» #3c3460 @iphone @app @data';

export default async function (app) {
  requireMonitoringOptIn();
  const minutes = Number(process.env.BANCI_MONITOR_MINUTES || 5);
  await startMonitoring(app);

  const target = minutes * 60;
  const end = Date.now() + target * 1000 + 60000;
  let prev = await timerSeconds(app);
  while (prev < target) {
    assert(Date.now() < end, `таймер дошёл до ${target} с за отведённое время (сейчас ${prev} с)`);
    await new Promise((r) => setTimeout(r, 10000)); // интервал опроса состояния, не ожидание результата
    const state = await app.appState();
    assert(state === 4, `Banci на переднем плане, не упала (queryAppState=${state})`);
    assert(!(await app.exists(by.contains('הניטור הופסק'))), 'нет листа «הניטור הופסק» во время мониторинга');
    assert(await app.exists(by.exact('תקין')), `статус «תקין» на ${prev} с мониторинга`);
    const t = await timerSeconds(app);
    assert(t > prev, `таймер растёт (${prev} → ${t} с)`);
    prev = t;
  }

  await endMonitoring(app);
}
